{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2156-04-12 14:30:00",
      "speaker": "Doctor",
      "text": "Hello, I’m Dr. Lee, one of your oncology team members. We’ve admitted you today for your third cycle of R-ICE chemotherapy. How are you feeling?"
    },
    {
      "turn_number": 2,
      "time": "2156-04-12 14:31:00",
      "speaker": "Patient",
      "text": "Hi, Doctor. I’m okay—just the usual sinus pain, nothing new. I’m a bit tired, but my appetite’s been stable."
    },
    {
      "turn_number": 3,
      "time": "2156-04-12 14:32:00",
      "speaker": "Doctor",
      "text": "Good, no fevers or chills? Any nausea or abdominal pain?"
    },
    {
      "turn_number": 4,
      "time": "2156-04-12 14:33:00",
      "speaker": "Patient",
      "text": "No, nothing like that. Just the chronic sinus pressure. I’ve had it for months."
    },
    {
      "turn_number": 5,
      "time": "2156-04-12 14:34:00",
      "speaker": "Doctor",
      "text": "Understood. We’ll keep monitoring. Your blood counts came back low again—WBC 2.1, hemoglobin 8.7, platelets 63. That’s expected with R-ICE, but we’ll watch closely."
    },
    {
      "turn_number": 6,
      "time": "2156-04-12 14:35:00",
      "speaker": "Patient",
      "text": "They’ve been low before. Should I be worried?"
    },
    {
      "turn_number": 7,
      "time": "2156-04-12 14:36:00",
      "speaker": "Doctor",
      "text": "It’s expected, not dangerous right now. We’ll give your chemotherapy and support your counts. You’ve tolerated it well so far."
    },
    {
      "turn_number": 8,
      "time": "2156-04-12 14:37:00",
      "speaker": "Patient",
      "text": "Okay, thanks. I’ve been using my home meds as usual—methadone, Dilaudid, all of it."
    },
    {
      "turn_number": 9,
      "time": "2156-04-12 14:38:00",
      "speaker": "Doctor",
      "text": "Yes, we’ve restarted your home medications. We held metformin and glimepiride during admission but will restart them later with insulin coverage."
    },
    {
      "turn_number": 10,
      "time": "2156-04-12 14:39:00",
      "speaker": "Patient",
      "text": "My sugars have been high lately. Is that from the steroids?"
    },
    {
      "turn_number": 11,
      "time": "2156-04-12 14:40:00",
      "speaker": "Doctor",
      "text": "Exactly. Dexamethasone can raise blood sugar. We’re on a sliding scale insulin for now. We’ll watch it closely."
    },
    {
      "turn_number": 12,
      "time": "2156-04-12 15:00:00",
      "speaker": "Doctor",
      "text": "We also scheduled an MRI of your nasopharynx this afternoon to check how the skull base mass is responding."
    },
    {
      "turn_number": 13,
      "time": "2156-04-12 15:01:00",
      "speaker": "Patient",
      "text": "Oh, right. The last one showed improvement, didn’t it?"
    },
    {
      "turn_number": 14,
      "time": "2156-04-12 15:02:00",
      "speaker": "Doctor",
      "text": "Yes, after two cycles, there was a clear decrease in size. We’re hopeful this one shows more progress."
    },
    {
      "turn_number": 15,
      "time": "2156-04-12 18:30:00",
      "speaker": "Doctor",
      "text": "Hi again. Your MRI results are back. Good news—the mass in your skull base has decreased further. No new brain lesions."
    },
    {
      "turn_number": 16,
      "time": "2156-04-12 18:31:00",
      "speaker": "Patient",
      "text": "That’s great! Does that mean the chemo is working?"
    },
    {
      "turn_number": 17,
      "time": "2156-04-12 18:32:00",
      "speaker": "Doctor",
      "text": "Yes, it’s responding well. The asymmetry and enhancement are still there, but much improved. We’ll continue with R-ICE."
    },
    {
      "turn_number": 18,
      "time": "2156-04-12 18:33:00",
      "speaker": "Patient",
      "text": "And the hearing loss? Still from the eustachian tube blockage?"
    },
    {
      "turn_number": 19,
      "time": "2156-04-12 18:34:00",
      "speaker": "Doctor",
      "text": "Yes, fluid in the mastoids due to the mass pressing on the tube. No infection seen. ENT is monitoring."
    },
    {
      "turn_number": 20,
      "time": "2156-04-13 09:00:00",
      "speaker": "Doctor",
      "text": "We’re starting your R-ICE chemo today. It includes rituximab, ifosfamide, carboplatin, and etoposide, plus dexamethasone."
    },
    {
      "turn_number": 21,
      "time": "2156-04-13 09:01:00",
      "speaker": "Patient",
      "text": "Rituximab again? Because of the EBV?"
    },
    {
      "turn_number": 22,
      "time": "2156-04-13 09:02:00",
      "speaker": "Doctor",
      "text": "Exactly. Your EBV viral load was elevated, so we added rituximab to target those infected cells."
    },
    {
      "turn_number": 23,
      "time": "2156-04-13 09:03:00",
      "speaker": "Patient",
      "text": "Makes sense. Any side effects I should watch for?"
    },
    {
      "turn_number": 24,
      "time": "2156-04-13 09:04:00",
      "speaker": "Doctor",
      "text": "Fatigue, nausea, low blood counts. Ifosfamide can cause drowsiness—we’ll monitor you closely."
    },
    {
      "turn_number": 25,
      "time": "2156-04-14 10:00:00",
      "speaker": "Doctor",
      "text": "You did well overnight. But you were a bit drowsy this morning—any confusion?"
    },
    {
      "turn_number": 26,
      "time": "2156-04-14 10:01:00",
      "speaker": "Patient",
      "text": "Yeah, I felt really sleepy. Like I couldn’t focus. But I’m clearer now."
    },
    {
      "turn_number": 27,
      "time": "2156-04-14 10:02:00",
      "speaker": "Doctor",
      "text": "That’s likely from ifosfamide. It can cause temporary somnolence. Good that it’s improving. No weakness or numbness?"
    },
    {
      "turn_number": 28,
      "time": "2156-04-14 10:03:00",
      "speaker": "Patient",
      "text": "No, just sleepy. My back pain is the same—still managed with meds."
    },
    {
      "turn_number": 29,
      "time": "2156-04-14 10:04:00",
      "speaker": "Doctor",
      "text": "We’ll keep your pain regimen. Your hemoglobin dropped to 7.3, so we’ll give one unit of red blood cells today."
    },
    {
      "turn_number": 30,
      "time": "2156-04-14 10:05:00",
      "speaker": "Patient",
      "text": "Again? I remember needing that last time too."
    },
    {
      "turn_number": 31,
      "time": "2156-04-14 10:06:00",
      "speaker": "Doctor",
      "text": "Yes, anemia is common with chemo and your history. It’s not dangerous—we’re just supporting you through it."
    },
    {
      "turn_number": 32,
      "time": "2156-04-15 08:00:00",
      "speaker": "Doctor",
      "text": "Your blood counts are still low—WBC 1.6, platelets 50. But stable. No fever or infection signs."
    },
    {
      "turn_number": 33,
      "time": "2156-04-15 08:01:00",
      "speaker": "Patient",
      "text": "Will I need another platelet transfusion?"
    },
    {
      "turn_number": 34,
      "time": "2156-04-15 08:02:00",
      "speaker": "Doctor",
      "text": "Not right now. We’ll watch. You’re not bleeding, so we can wait. Your body just needs time to recover."
    },
    {
      "turn_number": 35,
      "time": "2156-04-15 08:03:00",
      "speaker": "Patient",
      "text": "And after this cycle? What’s next?"
    },
    {
      "turn_number": 36,
      "time": "2156-04-15 08:04:00",
      "speaker": "Doctor",
      "text": "We’re discussing transplant options—possibly allogeneic, given your poor marrow reserve."
    },
    {
      "turn_number": 37,
      "time": "2156-04-15 08:05:00",
      "speaker": "Patient",
      "text": "That sounds intense. Is it necessary?"
    },
    {
      "turn_number": 38,
      "time": "2156-04-15 08:06:00",
      "speaker": "Doctor",
      "text": "It’s a possibility, not a plan yet. We’ll evaluate after this cycle and see if your counts recover enough."
    },
    {
      "turn_number": 39,
      "time": "2156-04-16 09:00:00",
      "speaker": "Doctor",
      "text": "You’re doing well. We’re planning discharge tomorrow. You’ll start filgrastim at home to help your white count."
    },
    {
      "turn_number": 40,
      "time": "2156-04-16 09:01:00",
      "speaker": "Patient",
      "text": "I have it at home. How long do I use it?"
    },
    {
      "turn_number": 41,
      "time": "2156-04-16 09:02:00",
      "speaker": "Doctor",
      "text": "Daily until your follow-up. We’ll decide then if you need more. Also, keep checking your blood sugar twice a day."
    },
    {
      "turn_number": 42,
      "time": "2156-04-16 09:03:00",
      "speaker": "Patient",
      "text": "Because of the dexamethasone?"
    },
    {
      "turn_number": 43,
      "time": "2156-04-16 09:04:00",
      "speaker": "Doctor",
      "text": "Yes. Your last fingerstick was 320. If it stays over 300, call your oncologist."
    },
    {
      "turn_number": 44,
      "time": "2156-04-16 09:05:00",
      "speaker": "Patient",
      "text": "Got it. And my other meds—everything goes back to normal?"
    },
    {
      "turn_number": 45,
      "time": "2156-04-16 09:06:00",
      "speaker": "Doctor",
      "text": "Yes, all your home meds resume—methadone, Dilaudid, acyclovir, atovaquone, and your thyroid and diabetes pills."
    },
    {
      "turn_number": 46,
      "time": "2156-04-16 09:07:00",
      "speaker": "Patient",
      "text": "And IVIG? I’m due soon."
    },
    {
      "turn_number": 47,
      "time": "2156-04-16 09:08:00",
      "speaker": "Doctor",
      "text": "Yes, you’re scheduled for IVIG in four weeks. We’ll coordinate with your immunology team."
    },
    {
      "turn_number": 48,
      "time": "2156-04-17 10:00:00",
      "speaker": "Doctor",
      "text": "You’re cleared to go home. Follow up with Dr. Patel in one week for blood work."
    },
    {
      "turn_number": 49,
      "time": "2156-04-17 10:01:00",
      "speaker": "Patient",
      "text": "Thank you. I feel okay—tired, but no new symptoms."
    },
    {
      "turn_number": 50,
      "time": "2156-04-17 10:02:00",
      "speaker": "Doctor",
      "text": "You did well. Keep using filgrastim, check sugars, and call if you feel feverish or worse."
    },
    {
      "turn_number": 51,
      "time": "2156-04-17 10:03:00",
      "speaker": "Patient",
      "text": "I will. And I’ll see you all next week."
    },
    {
      "turn_number": 52,
      "time": "2156-04-17 10:04:00",
      "speaker": "Doctor",
      "text": "Take care. We’re glad the tumor is shrinking and you’re stable."
    },
    {
      "turn_number": 53,
      "time": "2156-04-17 10:05:00",
      "speaker": "Patient",
      "text": "Me too. Thanks for everything."
    },
    {
      "turn_number": 54,
      "time": "2156-04-17 10:06:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Rest up and we’ll see you soon."
    },
    {
      "turn_number": 55,
      "time": "2156-04-17 10:07:00",
      "speaker": "Patient",
      "text": "Will do."
    },
    {
      "turn_number": 56,
      "time": "2156-04-17 10:08:00",
      "speaker": "Doctor",
      "text": "Nurse will go over your discharge instructions and meds now."
    },
    {
      "turn_number": 57,
      "time": "2156-04-17 10:09:00",
      "speaker": "Patient",
      "text": "Okay, thanks again."
    },
    {
      "turn_number": 58,
      "time": "2156-04-17 10:10:00",
      "speaker": "Doctor",
      "text": "Take care. We’re here if you need us."
    },
    {
      "turn_number": 59,
      "time": "2156-04-17 10:11:00",
      "speaker": "Patient",
      "text": "I appreciate it."
    },
    {
      "turn_number": 60,
      "time": "2156-04-17 10:12:00",
      "speaker": "Doctor",
      "text": "Have a safe trip home."
    },
    {
      "turn_number": 61,
      "time": "2156-04-17 10:13:00",
      "speaker": "Patient",
      "text": "Thank you."
    },
    {
      "turn_number": 62,
      "time": "2156-04-17 10:14:00",
      "speaker": "Doctor",
      "text": "We’ll talk at your follow-up."
    },
    {
      "turn_number": 63,
      "time": "2156-04-17 10:15:00",
      "speaker": "Patient",
      "text": "Looking forward to it."
    },
    {
      "turn_number": 64,
      "time": "2156-04-17 10:16:00",
      "speaker": "Doctor",
      "text": "Rest well."
    },
    {
      "turn_number": 65,
      "time": "2156-04-17 10:17:00",
      "speaker": "Patient",
      "text": "I will."
    },
    {
      "turn_number": 66,
      "time": "2156-04-17 10:18:00",
      "speaker": "Doctor",
      "text": "See you soon."
    },
    {
      "turn_number": 67,
      "time": "2156-04-17 10:19:00",
      "speaker": "Patient",
      "text": "Bye."
    }
  ],
  "summary": {
    "admission_start": "2156-04-12 14:28:00",
    "admission_end": "2156-04-17 17:43:00",
    "summary_paragraph": "The patient was admitted for her third cycle of R-ICE chemotherapy for EBV-positive classical Hodgkin lymphoma with skull base and nasopharyngeal involvement, following a good response after two prior cycles. She tolerated treatment with mild somnolence from ifosfamide, which resolved, and required a single unit of packed red blood cells due to anemia. Her white blood cell and platelet counts remained low but stable, without infection. An MRI showed continued regression of the skull base mass with no new intracranial lesions. She was discharged home with instructions to start filgrastim, monitor blood glucose due to steroid-induced hyperglycemia, and follow up for blood counts and transplant evaluation. Her chronic conditions, including CVID, diabetes, and back pain, were managed throughout.",
    "problems": [
      "Encounter for antineoplastic chemotherapy",
      "Primary central nervous system lymphoma, lymph nodes of head, face, and neck",
      "Common variable immunodeficiency",
      "Hodgkin's disease, unspecified type, lymph nodes of head, face, and neck",
      "Unspecified sinusitis (chronic)",
      "Diabetes mellitus without mention of complication, type II or unspecified type, uncontrolled",
      "Antineoplastic chemotherapy induced anemia",
      "Other chronic pain",
      "Backache, unspecified",
      "Colostomy status",
      "Esophagitis, unspecified",
      "Depressive disorder, not elsewhere classified",
      "Panic disorder without agoraphobia",
      "Asthma, unspecified type, unspecified",
      "Unspecified acquired hypothyroidism"
    ]
  }
}
